import urllib.request, json; req = urllib.request.Request('https://api.github.com/repos/felix16805/social-media-content-analyzer/actions/runs/32867460335/jobs', headers={'Accept': 'application/vnd.github+json'}); res = urllib.request.urlopen(req); jobs = json.loads(res.read()).get('jobs', []); print('\n'.join([str(j['id']) + ': ' + j['name'] + ' - ' + str(j['conclusion']) for j in jobs]))
